```rust
fn longest_run<T: PartialEq>(items: &[T]) -> Option<(&T, usize)> {
    if items.is_empty() {
        return None;
    }
    let mut best_value = &items[0];
    let mut best_len = 1usize;
    let mut cur_value = &items[0];
    let mut cur_len = 1usize;

    for item in &items[1..] {
        if item == cur_value {
            cur_len += 1;
        } else {
            cur_value = item;
            cur_len = 1;
        }
        if cur_len > best_len {
            best_len = cur_len;
            best_value = cur_value;
        }
    }
    Some((best_value, best_len))
}

fn main() {
    assert_eq!(longest_run(&[1, 1, 2, 2, 2, 3]), Some((&2, 3)));
    assert_eq!(longest_run::<i32>(&[]), None);
    println!("ok");
}
```

Empty slices return `None`, avoiding a panic on the index. The single pass is O(n) and the generic bound lets it work on any `PartialEq` type.

