from datetime import datetime, timezone


def parse_iso_date(text: str):
    """Return a datetime for an ISO-8601 string, or None if it can't be parsed."""
    if not isinstance(text, str) or not text:
        return None
    value = text.strip()
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(value)
    except (ValueError, OverflowError):
        return None


if __name__ == "__main__":
    assert parse_iso_date("2024-01-02") == datetime(2024, 1, 2)
    assert parse_iso_date("2024-01-02T03:04:05Z") == datetime(
        2024, 1, 2, 3, 4, 5, tzinfo=timezone.utc
    )
    assert parse_iso_date(" 2024-06-01T00:00:00 ") == datetime(2024, 6, 1)
    assert parse_iso_date("not a date") is None
    assert parse_iso_date("") is None
    assert parse_iso_date("2024-13-40") is None
    print("parse tests passed")
```

Wraps `datetime.fromisoformat`, normalises a trailing `Z` to `+00:00`, trims surrounding whitespace, and converts both `ValueError` and `OverflowError` into `None`. Inputs that are empty, non-string, or out of range all return `None` cleanly.

