```rust
use std::collections::HashMap;

pub fn parse_config(input: &str) -> Result<HashMap<String, String>, String> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (k, v) = line
            .split_once('=')
            .ok_or_else(|| format!("line {}: missing '='", idx + 1))?;
        let key = k.trim();
        if key.is_empty() {
            return Err(format!("line {}: empty key", idx + 1));
        }
        if map.insert(key.to_string(), v.trim().to_string()).is_some() {
            return Err(format!("line {}: duplicate key '{}'", idx + 1, key));
        }
    }
    Ok(map)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dedups_and_trims() {
        let cfg = "# comment\n\nhost = localhost\nport=8080\n";
        let m = parse_config(cfg).unwrap();
        assert_eq!(m["host"], "localhost");
        assert_eq!(m["port"], "8080");
    }

    #[test]
    fn rejects_missing_equals() {
        assert!(parse_config("novalue").is_err());
    }
}
