#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

void print(Node* head) {
    for (Node* cur = head; cur; cur = cur->next)
        std::cout << cur->value << (cur->next ? " -> " : "");
    std::cout << "\n";
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    print(head);            // 1 -> 2 -> 3
    head = reverse(head);
    print(head);            // 3 -> 2 -> 1
    return 0;
}
