import re

_DIGITS = re.compile(r"\D")


def to_e164_us(raw: str) -> str:
    """Normalize a US number to +1XXXXXXXXXX or raise ValueError."""
    if not isinstance(raw, str):
        raise TypeError("phone number must be a string")
    digits = _DIGITS.sub("", raw)
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) != 10:
        raise ValueError(f"expected 10 digits, got {len(digits)}")
    if digits[0] in "01":
        raise ValueError("area code cannot start with 0 or 1")
    if digits[3] in "01":
        raise ValueError("exchange cannot start with 0 or 1")
    return "+1" + digits


if __name__ == "__main__":
    assert to_e164_us("(415) 555-2671") == "+14155552671"
    assert to_e164_us("1-415-555-2671") == "+14155552671"
    assert to_e164_us("415.555.2671") == "+14155552671"
    for bad in ("", "12345", "0155551234", "4150551234", "41555526711"):
        try:
            to_e164_us(bad)
            raise AssertionError(f"should have rejected {bad!r}")
        except ValueError:
            pass
    print("all passed")
```

