// stats.cpp: mean and sample standard deviation from whitespace-separated input.
#include <cmath>
#include <iomanip>
#include <iostream>
#include <vector>

int main() {
    std::vector<double> values;
    double x = 0.0;
    while (std::cin >> x) {
        values.push_back(x);
    }
    if (values.empty()) {
        std::cerr << "error: no numeric input\n";
        return 1;
    }
    double sum = 0.0;
    for (double v : values) {
        sum += v;
    }
    const double mean = sum / static_cast<double>(values.size());
    double sq = 0.0;
    for (double v : values) {
        sq += (v - mean) * (v - mean);
    }
    const double variance =
        values.size() > 1 ? sq / static_cast<double>(values.size() - 1) : 0.0;
    std::cout << std::fixed << std::setprecision(4)
              << "count=" << values.size() << " mean=" << mean
              << " stddev=" << std::sqrt(variance) << '\n';
    return 0;
}
