import re

PATTERN = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def is_valid_email(text):
    if not isinstance(text, str):
        return False
    return bool(PATTERN.match(text))


def main():
    samples = [
        "alice@example.com",
        "a.b-c+tag@sub.example.co",
        "no-at-sign",
        "user@domain",
        "user@domain.c",
        "",
    ]
    for sample in samples:
        verdict = "valid" if is_valid_email(sample) else "invalid"
        print(f"{sample!r}: {verdict}")


if __name__ == "__main__":
    main()
```

This is a shape check, not a deliverability check — it catches obvious mistakes like a missing `@` or a one-letter TLD. No email regex is truly RFC-compliant, so the pattern stays deliberately narrow, anchoring with `^` and `$` and requiring at least two TLD letters. Non-string input returns `False` instead of raising.

A self-contained word-frequency counter with a basic hash table and qsort:

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAP 4096
#define MAXWORD 128

typedef struct { char *word; long count; } Entry;

static Entry table[CAP];
static size_t used = 0;

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h;
}

static int cmp(const void *a, const void *b) {
    const Entry *x = a, *y = b;
    return strcmp(x->word, y->word);
}

int main(void) {
    char word[MAXWORD];
    int c;
    size_t len = 0;

    while ((c = getchar()) != EOF) {
        if (isalpha(c) || c == '\'') {
            if (len + 1 < MAXWORD) word[len++] = (char)tolower(c);
        } else if (len > 0) {
            word[len] = '\0';
            size_t idx = hash(word) % CAP;
            while (table[idx].word) {
                if (strcmp(table[idx].word, word) == 0) {
                    table[idx].count++;
                    goto next;
                }
                idx = (idx + 1) % CAP;
            }
            table[idx].word = strdup(word);
            table[idx].count = 1;
            used++;
next:
            len = 0;
        }
    }

    Entry out[CAP];
    size_t n = 0;
    for (size_t i = 0; i < CAP; i++)
        if (table[i].word) out[n++] = table[i];

    qsort(out, n, sizeof(Entry), cmp);
    for (size_t i = 0; i < n; i++)
        printf("%s %ld\n", out[i].word, out[i].count);
    return 0;
}
```

Edge handling: empty input prints nothing; words longer than 127 chars are truncated rather than overflowing; apostrophes are kept so "don't" stays one token. Compile with `cc -O2 -Wall -o wf wf.c`.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }

    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8];
    println!("{:?}", merge_sorted(&a, &b));
    println!("{:?}", merge_sorted::<i32>(&[], &[]));
}
```

Only the output Vec owns data; both inputs are borrowed. Ties take from the left slice first, which keeps the merge stable. Capacity is preallocated to avoid reallocation during pushes.

