```cpp
#include <iostream>
#include <stack>
#include <string>
#include <utility>
#include <vector>

struct Result {
    bool ok;
    std::size_t index;   // position of first error; only valid when !ok
    char expected;       // closing char expected there
};

Result check_brackets(const std::string& s) {
    std::vector<std::pair<char, char>> pairs = {{'(', ')'}, {'[', ']'}, {'{', '}'}};
    std::stack<std::pair<char, std::size_t>> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        bool opening = false;
        for (auto& p : pairs) {
            if (c == p.first) { st.push({c, i}); opening = true; break; }
        }
        if (opening) continue;
        for (auto& p : pairs) {
            if (c == p.second) {
                if (st.empty() || st.top().first != p.first) {
                    return {false, i, p.first};
                }
                st.pop();
                break;
            }
        }
    }
    if (!st.empty()) {
        // report the mismatched opening at its own position
        for (auto& p : pairs) {
            if (p.first == st.top().first) return {false, st.top().second, p.second};
        }
    }
    return {true, 0, '\0'};
}

int main() {
    auto a = check_brackets("a(b[c]{d})e");
    std::cout << (a.ok ? "ok" : "fail") << '\n';
    auto b = check_brackets("a(b[c)d]");
    std::cout << b.ok << ' ' << b.index << '\n';   // 0, index 5
    auto c = check_brackets("(abc");
    std::cout << c.ok << ' ' << c.index << ' ' << c.expected << '\n'; // 0, 0, ')'
    return 0;
}
```

Non-bracket characters are ignored. For an unclosed opening bracket the function reports that bracket's own index and the matching closer it wanted.

