#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(Node* head) {
    for (Node* cur = head; cur != nullptr; cur = cur->next)
        std::cout << cur->value << (cur->next ? " " : "\n");
}

void destroy(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;
    for (int v : {1, 2, 3, 4, 5})
        head = new Node{v}, head->next = (head->next, head);
    return 0;
}
