```python

def is_balanced(s: str) -> bool:
    """True if every bracket in s is correctly closed and nested."""
    pairs = {")": "(", "]": "[", "}": "{"}
    openers = set(pairs.values())
    stack = []
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


if __name__ == "__main__":
    assert is_balanced("{[()]}")
    assert not is_balanced("([)]")
    assert not is_balanced("(((")
    assert is_balanced("")
    print("all checks passed")
```

The stack holds only unclosed openers. A closer with an empty stack or a mismatched top fails immediately, and the final `not stack` catches leftovers like `(((`.

```rust
fn fib(n: u32) -> Option<u128> {
    let mut a: u128 = 0;
    let mut b: u128 = 1;
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    for n in [0u32, 1, 2, 10, 100, 200] {
        match fib(n) {
            Some(v) => println!("fib({n}) = {v}"),
            None => println!("fib({n}) overflows u128"),
        }
    }

    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(100), Some(354224848179261915075));
    assert_eq!(fib(200), None);
}
```

`checked_add` returns `None` on overflow, so `fib(200)` (which exceeds u128) yields `None` instead of panicking. fib(0) = 0, fib(1) = 1.

