#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data{1, 3, 5, 7, 9, 11};
    std::cout << binary_search(data, 7) << '\n';
    std::cout << binary_search(data, 2) << '\n';
    std::cout << binary_search({}, 5) << '\n';
    return 0;
}
