```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right--;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[64] = "hello, world";
    reverse_in_place(buf);
    printf("%s\n", buf);

    char empty[1] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);

    char *p = NULL;
    reverse_in_place(p); /* safe no-op */

    char unicode[] = "na\xc3\xafve caf\xc3\xa9";
    reverse_in_place(unicode);
    printf("%s\n", unicode); /* bytes reversed, not graphemes */
    return 0;
}
```

`right` starts at `strlen(s) - 1` so the terminating NUL is never touched. A NULL pointer returns immediately, and an empty string (length 0) returns before decrementing. Note the last case: reversing multibyte UTF-8 bytes scrambles the encoding — that is correct byte-level behavior, and a grapheme-aware version would need a UTF-8 decoder.

