```rust
fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();

    // Keep the shorter string as the column set to bound memory.
    let (rows, cols) = if a.len() >= b.len() { (a, b) } else { (b, a) };

    let mut prev: Vec<usize> = (0..=cols.len()).collect();
    let mut curr: Vec<usize> = vec![0; cols.len() + 1];

    for i in 1..=rows.len() {
        curr[0] = i;
        for j in 1..=cols.len() {
            let cost = if rows[i - 1] == cols[j - 1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1)
                .min(curr[j - 1] + 1)
                .min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    prev[cols.len()]
}

fn main() {
    assert_eq!(levenshtein("kitten", "sitting"), 3);
    assert_eq!(levenshtein("", "abc"), 3);
    assert_eq!(levenshtein("abc", ""), 3);
    assert_eq!(levenshtein("café", "cafe"), 1);
    println!("ok");
}
```

Collects `chars()` so multi-byte Unicode scalars count as one unit, swaps the strings so the column vector is the shorter one, and rolls two rows instead of a full matrix. The `café`/`cafe` case yields 1 because the accented character is a single scalar and substitutes for `e`.

