```c
#include <stdio.h>
#include <stdint.h>

int popcount_kernighan(uint32_t n) {
    int count = 0;
    while (n) {
        n &= n - 1;  /* clears the lowest set bit */
        ++count;
    }
    return count;
}

int main(void) {
    struct { uint32_t value; int expected; } cases[] = {
        {0u, 0},
        {1u, 1},
        {0xFFFFFFFFu, 32},
        {0x80000000u, 1},
        {0x0000FFFFu, 16},
        {0xAAAAAAAAu, 16},
    };

    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        int got = popcount_kernighan(cases[i].value);
        printf("0x%08X -> %d (expected %d)\n",
               cases[i].value, got, cases[i].expected);
        if (got != cases[i].expected) {
            fprintf(stderr, "mismatch at case %zu\n", i);
            return 1;
        }
    }
    printf("all cases passed\n");
    return 0;
}
```

Kernighan's algorithm runs in O(number of set bits), faster than shifting all 32 positions. `n &= n - 1` clears the least-significant set bit each iteration.

