class FileDescriptor {
public:
    FileDescriptor() noexcept : fd_(-1) {}

    explicit FileDescriptor(const std::string& path, int flags = O_RDONLY) {
        fd_ = ::open(path.c_str(), flags);
        if (fd_ < 0) {
            throw std::runtime_error("open failed: " + path);
        }
    }

    ~FileDescriptor() { close_now(); }

    FileDescriptor(const FileDescriptor&) = delete;
    FileDescriptor& operator=(const FileDescriptor&) = delete;

    FileDescriptor(FileDescriptor&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    FileDescriptor& operator=(FileDescriptor&& other) noexcept {
        if (this != &other) {
            close_now();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

    ssize_t read_some(char* buf, size_t n) const {
        if (fd_ < 0) {
            throw std::logic_error("read on invalid descriptor");
        }
        return ::read(fd_, buf, n);
    }

private:
    void close_now() noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }

    int fd_;
};

int main() {
    try {
        FileDescriptor f("cpp_raii_example.cpp");
        char buf[64];
        ssize_t n = f.read_some(buf, sizeof(buf));
        std::cout << "read " << n << " bytes\n";
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n";
        return 1;
    }

