class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.cap = capacity
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return -1
        value = self.data.pop(key)
        self.data[key] = value  # reinsert at end
        return value

    def put(self, key, value) -> None:
        if key in self.data:
            self.data.pop(key)
        elif len(self.data) >= self.cap:
            oldest = next(iter(self.data))
            self.data.pop(oldest)
        self.data[key] = value

