from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[Any, Any]" = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            self.misses += 1
            return None
        self._data.move_to_end(key)
        self.hits += 1
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


def memoize(cache: LRUCache):
    def wrap(fn):
        def wrapped(*args):
            cached = cache.get(args)
            if cached is None:
                cached = fn(*args)
                cache.put(args, cached)
            return cached
        return wrapped
    return wrap


if __name__ == "__main__":
    cache = LRUCache(2)

    @memoize(cache)
    def slow_square(n: int) -> int:
        return n * n

    assert slow_square(4) == 16
    assert slow_square(4) == 16        # hit
    assert slow_square(5) == 25
    assert slow_square(4) == 16        # still cached
    assert slow_square(6) == 36        # evicts 5
    assert cache.get((5,)) is None     # 5 was evicted
    print(cache.hits, cache.misses)
```

`move_to_end` marks a key as most-recently-used on every access. `popitem(last=False)` evicts the oldest when over capacity. A `None` return from `get` means a miss, so store real `None` results under a wrapper key if your function can return `None`.

