```rust
use std::collections::HashMap;

struct Node<K> {
    key: K,
    prev: usize,
    next: usize,
}

/// LRU cache with O(1) get/put, capacity >= 1.
pub struct LruCache<K: std::hash::Hash + Eq + Clone, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K>>,
    values: Vec<V>,
    head: usize, // most recently used
    tail: usize, // least recently used
    cap: usize,
    nil: usize, // sentinel index meaning "none"
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "capacity must be >= 1");
        LruCache {
            map: HashMap::new(),
            nodes: Vec::new(),
            values: Vec::new(),
            head: 0,
            tail: 0,
            cap,
            nil: usize::MAX,
        }
    }

    fn unlink(&mut self, i: usize) {
        let (p, n) = (self.nodes[i].prev, self.nodes[i].next);
        if p != self.nil { self.nodes[p].next = n; } else { self.head = n; }
        if n != self.nil { self.nodes[n].prev = p; } else { self.tail = p; }
    }

    fn push_front(&mut self, i: usize) {
        self.nodes[i].prev = self.nil;
        self.nodes[i].next = self.head;
        if self.head != self.nil { self.nodes[self.head].prev = i; }
        self.head = i;
        if self.tail == self.nil { self.tail = i; }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let &i = self.map.get(key)?;
        if i != self.head {
            self.unlink(i);
            self.push_front(i);
        }
        Some(&self.values[i])
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&i) = self.map.get(&key) {
            self.values[i] = value;
            if i != self.head {
                self.unlink(i);
                self.push_front(i);
            }
            return;
        }
        let i = self.nodes.len();
        self.nodes.push(Node { key: key.clone(), prev: self.nil, next: self.nil });
        self.values.push(value);
        self.map.insert(key, i);
        self.push_front(i);
        if self.map.len() > self.cap {
            let victim = self.tail;
            self.unlink(victim);
            self.map.remove(&self.nodes[victim].key);
        }
    }
}

