def csv_to_json(rows: list[dict[str, str]]) -> str:
    """Serialize cleaned rows to indented JSON."""
    cleaned = []
    for row in rows:
        out = {}
        for key, value in row.items():
            if key is None:  # csv adds None key for ragged rows
                continue
            out[key.strip()] = value.strip() if isinstance(value, str) else value
        if any(v != "" for v in out.values()):
