        print(f"usage: {argv[0]} input.csv output.json", file=sys.stderr)
        return 2

    with open(argv[1], newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        rows = list(reader)

    with open(argv[2], "w", encoding="utf-8") as fh:
        fh.write(csv_to_json(rows))
    return 0


