#include <iostream>
#include <stdexcept>
#include <utility>

template <typename T>
class DynArray {
public:
    DynArray() = default;
    ~DynArray() { delete[] data_; }

    DynArray(const DynArray&) = delete;
    DynArray& operator=(const DynArray&) = delete;

    void push_back(const T& value) {
        if (size_ == capacity_) grow();
        data_[size_++] = value;
    }

    std::size_t size() const { return size_; }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("DynArray::at");
        return data_[i];
    }

private:
    void grow() {
        std::size_t next = capacity_ == 0 ? 1 : capacity_ * 2;
        T* fresh = new T[next];
        for (std::size_t i = 0; i < size_; ++i) fresh[i] = data_[i];
        delete[] data_;
        data_ = fresh;
        capacity_ = next;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t capacity_ = 0;
};

int main() {
    DynArray<int> a;
    for (int i = 0; i < 5; ++i) a.push_back(i * 10);
    std::cout << a.size() << "\n";
    std::cout << a.at(3) << "\n";
    try {
        std::cout << a.at(99) << "\n";
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
