#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int value; struct Node *next; } Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; i--) list = push(list, i);

    list = reverse(list);

    for (Node *cur = list; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");

    while (list) {
        Node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}
```

The reversal is the standard three-pointer walk, O(n) time and O(1) extra space. It works on empty lists (returns NULL) and single-node lists unchanged. `push` builds the list head-first, so the printed order after reversal is `5 -> 4 -> 3 -> 2 -> 1`.

