// Reverse a null-terminated string in place. Returns false on null input.
bool reverse_in_place(char* s) {
    if (s == nullptr) return false;
    size_t n = strlen(s);
    if (n == 0) return true;
    for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
    return true;
}

