from collections.abc import Iterable


def flatten(items, max_depth=None):
    """Flatten arbitrarily nested iterables up to max_depth.

    Strings and bytes are treated as scalars, not iterables.
    max_depth=None means fully recursive; 0 means no flattening.
    """
    depth = 0 if max_depth is None else max_depth
    for item in items:
        if isinstance(item, (str, bytes)):
            yield item
        elif isinstance(item, Iterable):
            if max_depth is None or depth < max_depth:
                yield from flatten(item, None if max_depth is None else depth - 1)
            else:
                yield item
        else:
            yield item


