def longest_palindrome(s: str) -> str:
    """Expand around every center; returns the first longest palindrome found."""
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1  # shrink to the last valid bounds

    for i in range(len(s)):
        # odd-length: single character center
        l1, r1 = expand(i, i)
        # even-length: center between i and i+1
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    tests = {"babad": "bab", "cbbd": "bb", "": "", "a": "a",
             "forgeeksskeegfor": "geeksskeeg", "\u4e2d\u6587\u5b57": "\u4e2d\u6587\u5b57"}
    for text, expected in tests.items():
        got = longest_palindrome(text)
        assert len(got) == len(expected), (text, got, expected)
    print("ok")
```
Both odd and even centers are checked at each index, which is what makes a single loop sufficient. The `expand` helper walks outward and returns the last valid `(lo, hi)` after the loop overruns by one on each side. Comparison uses length only, so ties keep the earliest palindrome. Unicode code points work because Python strings index by code point, not byte.

