```python
import heapq

class RunningMedian:
    def __init__(self):
        # max-heap of the lower half (negated), min-heap of the upper half
        self.low = []
        self.high = []

    def add(self, value):
        if not self.low or value <= -self.low[0]:
            heapq.heappush(self.low, -value)
        else:
            heapq.heappush(self.high, value)
        # rebalance: low may exceed high by at most 1
        if len(self.low) > len(self.high) + 1:
            heapq.heappush(self.high, -heapq.heappop(self.low))
        elif len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self):
        if not self.low:
            return None
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2.0
        return float(-self.low[0])


if __name__ == "__main__":
    rm = RunningMedian()
    for n in [5, 2, 9, 2, 7]:
        rm.add(n)
        print(rm.median())
    # 5.0, 3.5, 5.0, 3.5, 5.0
```
Two heaps split the stream so the median is always at their tops. Duplicates push to `low` consistently, and rebalancing keeps the sizes within one, so `median()` is O(1) and `add()` is O(log n). Empty input returns `None` rather than raising.

```cpp
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <vector>

std::uint32_t fnv1a(const std::vector<char>& data, std::uint32_t hash = 2166136261u) {
    for (unsigned char byte : data) {
        hash ^= byte;
        hash *= 16777619u;
    }
    return hash;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: fnv FILE\n";
        return 2;
    }
    std::ifstream in(argv[1], std::ios::binary);
    if (!in) {
        std::cerr << "cannot open " << argv[1] << '\n';
        return 1;
    }

    constexpr std::size_t CHUNK = 1 << 16;
    std::vector<char> buf(CHUNK);
    std::uint32_t hash = 2166136261u;
    while (in) {
        in.read(buf.data(), static_cast<std::streamsize>(buf.size()));
        std::streamsize n = in.gcount();
        if (n > 0) {
            buf.resize(static_cast<std::size_t>(n));
            hash = fnv1a(buf, hash);
            buf.resize(CHUNK);
        }
    }

    std::cout << std::hex << std::setw(8) << std::setfill('0') << hash << '\n';
    return 0;
}
```

Opening with `std::ios::binary` prevents the C++ runtime from translating `\r\n` on Windows, which would change the bytes and the hash. The loop reads 64 KiB at a time; `gcount()` returns however many bytes actually arrived on the final short read, and the vector is resized down to that count so the hash only sees real data. The FNV-1a constants are the standard 32-bit ones: offset basis `2166136261u` and prime `16777619u`, with xor before multiply. Passing `hash` back in each call lets the chunks chain into one digest. Output is zero-padded to eight hex digits so short hashes stay aligned.

