class StringMap {
public:
    explicit StringMap(std::size_t buckets) : slots_(buckets) {}

    void put(const std::string& key, int value) {
        std::size_t idx = fnv1a(key) % slots_.size();
        while (slots_[idx].has_value()) {
            if (slots_[idx]->first == key) {
                slots_[idx]->second = value;
                return;
            }
            idx = (idx + 1) % slots_.size();
        }
        slots_[idx] = std::make_pair(key, value);
    }

    std::optional<int> get(const std::string& key) const {
        std::size_t idx = fnv1a(key) % slots_.size();
        while (slots_[idx].has_value()) {
            if (slots_[idx]->first == key) {
                return slots_[idx]->second;
            }
            idx = (idx + 1) % slots_.size();
        }
        return std::nullopt;
    }

private:
    using Slot = std::optional<std::pair<std::string, int>>;
    std::vector<Slot> slots_;
};
