```c
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

typedef struct {
    int *buf;
    size_t cap;
    size_t head;  /* next read */
    size_t count; /* number of live elements */
} Ring;

void ring_init(Ring *r, int *storage, size_t capacity) {
    r->buf = storage;
    r->cap = capacity;
    r->head = 0;
    r->count = 0;
}

bool ring_empty(const Ring *r) { return r->count == 0; }
bool ring_full(const Ring *r)  { return r->count == r->cap; }

bool ring_push(Ring *r, int value) {
    if (ring_full(r)) return false;
    size_t tail = (r->head + r->count) % r->cap;
    r->buf[tail] = value;
    r->count++;
    return true;
}

bool ring_pop(Ring *r, int *out) {
    if (ring_empty(r)) return false;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % r->cap;
    r->count--;
    return true;
}

int main(void) {
    int storage[4];
    Ring r;
    ring_init(&r, storage, 4);

    for (int i = 1; i <= 5; i++) {
        bool ok = ring_push(&r, i);
        if (!ok) printf("push %d rejected: buffer full\n", i);
    }

    int v;
    while (ring_pop(&r, &v)) printf("popped %d\n", v);
    printf("drained; empty=%s\n", ring_empty(&r) ? "true" : "false");
    return 0;
}
```

Expected output: `push 5 rejected: buffer full`, then `popped 1` through `popped 4`, then `drained; empty=true`. No allocation happens after `ring_init`, so capacity is fixed by the caller's array size.

