#include <algorithm>
#include <cstddef>
#include <stdexcept>
#include <vector>

template <typename T>
T median(const std::vector<T>& values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::vector<T> copy(values);
    std::size_t mid = copy.size() / 2;
    std::nth_element(copy.begin(), copy.begin() + mid, copy.end());
    if (copy.size() % 2 == 1) {
        return copy[mid];
    }
    T upper = copy[mid];
    std::nth_element(copy.begin(), copy.begin() + mid - 1, copy.end());
    T lower = copy[mid - 1];
    return (lower + upper) / static_cast<T>(2);
}
