#include <iostream>
#include <string>
#include <limits>

int main() {
    std::string line;
    bool have = false;
    long long best = 0;
    while (std::getline(std::cin, line)) {
        // Strip surrounding whitespace.
        std::size_t start = line.find_first_not_of(" \t\r\n");
        if (start == std::string::npos) continue; // blank line
        std::size_t end = line.find_last_not_of(" \t\r\n");
        std::string trimmed = line.substr(start, end - start + 1);

        try {
            std::size_t pos = 0;
            long long value = std::stoll(trimmed, &pos);
            if (pos != trimmed.size()) {
                std::cerr << "skip (trailing junk): " << trimmed << "\n";
                continue;
            }
            if (!have || value > best) {
                best = value;
                have = true;
            }
            std::cout << "max=" << best << "\n";
        } catch (const std::exception&) {
            std::cerr << "skip (not a number): " << trimmed << "\n";
        }
    }
    if (!have) std::cout << "no numbers\n";
    return 0;
}
```

`std::stoll` reports how much of the string it consumed via `pos`, so a line like `42abc` is rejected instead of silently becoming 42. Blank lines and non-numeric lines go to stderr and don't disturb the running max. `best` starts unset and is only used once `have` is true, so all-negative input works correctly.

