#include <stdio.h>
#include <stdint.h>

int popcount32(uint32_t x) {
    int count = 0;
    while (x) {
        x &= x - 1;   /* clear lowest set bit */
        count++;
    }
    return count;
}

int main(void) {
    printf("%d\n", popcount32(0));          /* 0 */
    printf("%d\n", popcount32(1));          /* 1 */
    printf("%d\n", popcount32(0xFFFFFFFF)); /* 32 */
    return 0;
}
```
The `x &= x - 1` trick removes one set bit per iteration, so it runs once per set bit rather than once per bit.

