```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __contains__(self, key) -> bool:
        return key in self._data

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1     # 'a' becomes most recent
    cache.put("c", 3)              # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("all assertions passed")
```

`OrderedDict` preserves insertion order and `move_to_end` promotes a key on every access, so the front of the dict is always the least recently used entry. `popitem(last=False)` removes exactly that front item once capacity is exceeded. `get` returns `None` for a miss, and the `__main__` block exercises the eviction path so you can verify behaviour immediately.

