#include <string.h>

/* Returns 0 on success, -1 on invalid, -2 on overflow. Stores result in *out. */
int parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (end == s) return -1;           /* no digits consumed */
    while (*end == ' ' || *end == '\t') end++;
    if (*end != '\0') return -1;       /* trailing junk */
    if (errno == ERANGE || v == LONG_MAX || v == LONG_MIN) return -2;
    *out = v;
    return 0;
}

int main(void) {
    const char *tests[] = {"123", "-45", "  7 ", "12x", "", "99999999999999999999", NULL};
    for (int i = 0; tests[i]; i++) {
        long out = 0;
        int rc = parse_int(tests[i], &out);
        if (rc == 0) printf("ok   %-22s -> %ld\n", tests[i], out);
        else if (rc == -1) printf("bad  %-22s -> invalid\n", tests[i]);
        else printf("ovf  %-22s -> overflow\n", tests[i]);
    }
    return 0;
}
```

`strtol` sets `errno = ERANGE` on overflow; I reset it first. The `v == LONG_MAX` check catches the rare platform where `errno` is not set. Note `"  7 "` is accepted because leading whitespace is legal for `strtol` and I trim trailing spaces myself.

