```python
import threading
import time
from collections import deque


class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items = deque()
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)

    def put(self, item, timeout=None):
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._not_full:
            while len(self._items) >= self._capacity:
                remaining = None if deadline is None else deadline - time.monotonic()
                if remaining is not None and remaining <= 0:
                    raise TimeoutError("put timed out")
                if not self._not_full.wait(remaining):
                    raise TimeoutError("put timed out")
            self._items.append(item)
            self._not_empty.notify()

    def get(self, timeout=None):
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._not_empty:
            while not self._items:
                remaining = None if deadline is None else deadline - time.monotonic()
                if remaining is not None and remaining <= 0:
                    raise TimeoutError("get timed out")
                if not self._not_empty.wait(remaining):
                    raise TimeoutError("get timed out")
            item = self._items.popleft()
            self._not_full.notify()
            return item

    def __len__(self):
        with self._lock:
            return len(self._items)


if __name__ == "__main__":
    q = BoundedQueue(2)
    q.put(1)
    q.put(2)
    try:
        q.put(3, timeout=0.05)
        raise AssertionError("expected TimeoutError")
    except TimeoutError:
        pass
    assert q.get() == 1
    q.put(3, timeout=0.5)
    assert [q.get(), q.get(), q.get()] == [2, 3]
    assert len(q) == 0
    try:
        q.get(timeout=0.05)
        raise AssertionError("expected TimeoutError")
    except TimeoutError:
        pass
    print("bounded queue ok")
```

Each condition reuses the same lock, and the wait loop re-checks the predicate so a spurious wakeup cannot let a waiter past a full or empty bound.

