```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf{};
    std::size_t head_ = 0;  // next read index
    std::size_t size_ = 0;

public:
    bool push(const T& value) {
        if (size_ == N) return false;
        buf[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = buf[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 2;                 // full
    if (rb.pop() != 3 || rb.size() != 2) return 3;
    if (!rb.push(4)) return 4;                // wrap-around slot reused
    int expect[] = {2, 3, 4};
    for (int e : expect)
        if (rb.pop() != e) return 5;
    if (rb.pop().has_value()) return 6;
    std::cout << "ok\n";
}
```

`(head_ + size_) % N` finds the write slot without storing a tail index, so the full/empty states stay distinguishable.

