def longest_palindrome(s: str) -> str:
    """Longest palindromic substring via expand-around-center. O(n^2) time, O(1) space."""
    if not s:
        return ""

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi  # exclusive hi

    best_lo, best_hi = 0, 1
    for center in range(len(s)):
        for lo, hi in (expand(center, center), expand(center, center + 1)):
            if hi - lo > best_hi - best_lo:
                best_lo, best_hi = lo, hi
    return s[best_lo:best_hi]


