```rust
fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

/// Index where `target` is or would be inserted, keeping the slice sorted.
fn lower_bound<T: Ord>(slice: &[T], target: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if slice[mid] < *target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn main() {
    let data = [1, 3, 3, 5, 9];
    assert_eq!(binary_search(&data, &3), Some(1));
    assert_eq!(binary_search(&data, &4), None);
    assert_eq!(lower_bound(&data, &3), 1);
    assert_eq!(lower_bound(&data, &4), 3);
    assert_eq!(lower_bound(&data, &10), 5);
    assert_eq!(lower_bound(&[0u8; 0], &7), 0);
    println!("ok");
}
```
`lo + (hi - lo) / 2` avoids the overflow `(lo + hi) / 2` can hit, and `lower_bound` on an empty slice returns 0 rather than panicking.

