#include <algorithm>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
std::optional<T> median(std::vector<T> values) {
    if (values.empty()) {
        return std::nullopt;
    }
    std::sort(values.begin(), values.end());
    std::size_t n = values.size();
    if (n % 2 == 1) {
        return values[n / 2];
    }
    // Average the two middle elements. For integers this truncates;
    // the demonstration below uses doubles.
    return (values[n / 2 - 1] + values[n / 2]) / static_cast<T>(2);
}

int main() {
    std::vector<double> odd{3.0, 1.0, 2.0};
    std::vector<double> even{4.0, 1.0, 3.0, 2.0};
    std::vector<double> empty;

    std::cout << *median(odd) << '\n';    // 2
    std::cout << *median(even) << '\n';   // 2.5
    std::cout << (median(empty) ? "has value" : "no value") << '\n';
    return 0;
}
```

The parameter is taken by value because `sort` reorders it — the caller's vector is left untouched. Returning `std::optional<T>` makes the empty case explicit at the type level instead of returning a sentinel like `NaN` or `-1`. For floating point, averaging the halves avoids overflow that `(a + b) / 2` could hit with large `double` values near `DBL_MAX`.

