```c
#include <stdbool.h>
#include <stdio.h>
#include <limits.h>

bool is_power_of_two(long long n) {
    return n > 0 && (n & (n - 1)) == 0;
}

int main(void) {
    long long tests[] = {0, 1, 2, 3, 4, 8, 1024, -4, LLONG_MIN};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        printf("%lld -> %s\n", tests[i], is_power_of_two(tests[i]) ? "yes" : "no");
    }
    return 0;
}
```

A positive power of two has exactly one set bit, so `n & (n - 1)` clears it and leaves zero. The `n > 0` guard rejects zero and all negatives before the mask runs, which avoids the signed-overflow trap for `LLONG_MIN` (here `n - 1` is never evaluated for negatives).

```c
#include <stdio.h>
#include <stddef.h>

/* Return the index of key in arr[0..len), or -1 if absent.
 * arr must be sorted in ascending order. */
int binary_search(const int *arr, size_t len, int key)
{
    size_t low = 0;
    size_t high = len;

    while (low < high) {
        size_t mid = low + (high - low) / 2; /* no overflow */
        if (arr[mid] == key)
            return (int)mid;
        if (arr[mid] < key)
            low = mid + 1;
        else
            high = mid;
    }
    return -1;
}

int main(void)
{
    int data[] = {-7, -3, 0, 5, 11, 42, 99};
    size_t n = sizeof(data) / sizeof(data[0]);

    printf("found 42 at %d\n", binary_search(data, n, 42));
    printf("found 7 at %d\n", binary_search(data, n, 7));
    printf("empty at %d\n", binary_search(data, 0, 5));
    return 0;
}
```
The classic `(low + high) / 2` can overflow `size_t`, so the midpoint is computed as `low + (high - low) / 2`. The half-open range `[low, high)` makes the loop terminate cleanly, and a zero-length array returns -1 because the loop body never executes.

