use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ConfigError {
    MissingEquals(usize),
    EmptyKey(usize),
}

pub fn parse_config(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = match line.split_once('=') {
            Some(kv) => kv,
            None => return Err(ConfigError::MissingEquals(idx + 1)),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(idx + 1));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let text = "\n# comment\nhost = localhost\nport=8080\nempty=\n  spaced  =  value with spaces  \n";
    let cfg = parse_config(text).unwrap();
    assert_eq!(cfg.get("host").unwrap(), "localhost");
    assert_eq!(cfg.get("port").unwrap(), "8080");
    assert_eq!(cfg.get("empty").unwrap(), "");
    assert_eq!(cfg.get("spaced").unwrap(), "value with spaces");

    assert_eq!(parse_config("nokey\n"), Err(ConfigError::MissingEquals(1)));
    assert_eq!(parse_config("=v\n"), Err(ConfigError::EmptyKey(1)));
    assert_eq!(parse_config("\n#only comment\n").unwrap().len(), 0);
    println!("{:?}", cfg);
}
```

`lines()` strips line endings, `split_once('=')` keeps any `=` inside the value, and only the first `=` splits. Invalid lines return a typed error with the 1-based line number instead of panicking.

