// Reverse the order of non-space words, keeping the same spaces in place.
static std::string reverse_words(const std::string& s) {
    std::string out = s;
    int n = static_cast<int>(s.size());
    int i = 0;
    // Collect words in order, then write them back into the space slots
    // left-to-right. Non-space characters stay adjacent, so runs of spaces
    // are preserved exactly.
    std::string words;
    for (char c : s) {
        if (c != ' ') words.push_back(c);
    }
    std::string rev(words.rbegin(), words.rend());
    size_t ri = 0;
    for (int p = 0; p < n; ++p) {
        if (s[p] != ' ') out[p] = rev[ri++];
        else out[p] = ' ';
    }
    (void)i;
    return out;
}

int main() {
    assert(reverse_words("hello world") == "dlrow olleh");
    assert(reverse_words("  a  bc ") == "  cb  a ");
    assert(reverse_words("") == "");
    assert(reverse_words("   ") == "   ");
    std::cout << reverse_words("the quick brown fox") << "\n";
    return 0;
}
