// Iterative Euclid. Works for negatives by taking absolute values first.
long long gcd(long long a, long long b) {
    a = std::llabs(a);
    b = std::llabs(b);
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;  // gcd(0, 0) == 0 by convention
}

int main() {
    assert(gcd(48, 18) == 6);
    assert(gcd(18, 48) == 6);
    assert(gcd(-48, 18) == 6);
    assert(gcd(48, -18) == 6);
    assert(gcd(-48, -18) == 6);
    assert(gcd(0, 5) == 5);
    assert(gcd(5, 0) == 5);
    assert(gcd(0, 0) == 0);
    assert(gcd(7, 13) == 1);

    std::cout << "gcd checks passed\n";
    return 0;
}
```

`std::llabs` strips the sign so the remainder loop only sees non-negative values; otherwise `a % b` with a negative `a` yields a negative remainder and the loop terminates at a wrong value. `gcd(0, 0)` returns `0`, which is the conventional identity with no common divisors. The function is O(log min(|a|, |b|)) because each step strictly shrinks the second argument.

