#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <unordered_map>

std::uint64_t fib(std::uint64_t n) {
    static std::unordered_map<std::uint64_t, std::uint64_t> memo{{0, 0}, {1, 1}};
    if (n <= 93) {
        auto it = memo.find(n);
        if (it != memo.end()) return it->second;
        auto value = fib(n - 1) + fib(n - 2);
        memo.emplace(n, value);
        return value;
    }
    // Beyond 93 the result overflows uint64_t, so compute iteratively and reject.
    std::uint64_t a = 0, b = 1;
    for (std::uint64_t i = 2; i <= n; ++i) {
        if (a > UINT64_MAX - b) throw std::overflow_error("fib overflows uint64");
        std::uint64_t c = a + b;
        a = b;
        b = c;
    }
    return b;
}

int main() {
    if (fib(0) != 0 || fib(1) != 1) return 1;
    if (fib(10) != 55) return 2;
    if (fib(93) != 12200160415121876738ULL) return 3;
    try {
        fib(94);
        return 4;
    } catch (const std::overflow_error&) {
    }
    std::cout << "ok\n";
}
