template <typename T>
std::optional<T> safe_sum(const std::vector<T>& v) {
    using Wide = long long;
    Wide total = 0;
    for (T x : v) {
        total += static_cast<Wide>(x);
        if (total > std::numeric_limits<T>::max() ||
            total < std::numeric_limits<T>::min()) {
            return std::nullopt;
        }
    }
    return static_cast<T>(total);
}

int main() {
    std::vector<int> ok{1, 2, 3, 4};
    std::vector<int> big{std::numeric_limits<int>::max(), 1};
    auto a = safe_sum(ok);
    auto b = safe_sum(big);
    std::cout << (a ? std::to_string(*a) : "overflow") << '\n';
    std::cout << (b ? std::to_string(*b) : "overflow") << '\n';
    std::cout << (safe_sum<int>({}) ? "empty ok" : "empty overflow") << '\n';
    return 0;
}
