import heapq


class RunningMedian:
    def __init__(self):
        self.low = []   # max-heap via negated values
        self.high = []  # min-heap

    def add(self, value: int) -> None:
        heapq.heappush(self.low, -value)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self) -> float:
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2.0


if __name__ == "__main__":
    rm = RunningMedian()
    for n in (5, 1, 9, 3, 7):
        rm.add(n)
        print(n, "->", rm.median())
```
The heaps stay balanced to within one element, so `low` holds the smaller half and its root is the lower middle. The median is the lone middle element on odd counts and the mean of the two roots on even counts.

