use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

fn top_three(text: &str) -> Vec<(char, usize)> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for ch in text.chars() {
        *counts.entry(ch).or_insert(0) += 1;
    }
    let mut heap: BinaryHeap<(usize, Reverse<char>)> = counts
        .into_iter()
        .map(|(c, n)| (n, Reverse(c)))
        .collect();
    let mut out = Vec::new();
    for _ in 0..3 {
        match heap.pop() {
            Some((n, Reverse(c))) => out.push((c, n)),
            None => break,
        }
    }
    out
}

fn main() {
    println!("{:?}", top_three("hello world"));
    println!("{:?}", top_three(""));
}
