#include <cstdint>
#include <cstdio>

const std::int64_t MOD = 1000000007LL;

struct Mat {
    std::int64_t a00, a01, a10, a11;
};

Mat mul(const Mat& x, const Mat& y) {
    return Mat{
        (x.a00 * y.a00 + x.a01 * y.a10) % MOD,
        (x.a00 * y.a01 + x.a01 * y.a11) % MOD,
        (x.a10 * y.a00 + x.a11 * y.a10) % MOD,
        (x.a10 * y.a01 + x.a11 * y.a11) % MOD,
    };
}

std::int64_t fib(std::uint64_t n) {
    Mat result{1, 0, 0, 1}; // identity
    Mat base{1, 1, 1, 0};
    while (n > 0) {
        if (n & 1) result = mul(result, base);
        base = mul(base, base);
        n >>= 1;
    }
    return result.a01; // F(n)
}

int main() {
    std::printf("%lld\n", static_cast<long long>(fib(0)));  // 0
    std::printf("%lld\n", static_cast<long long>(fib(1)));  // 1
    std::printf("%lld\n", static_cast<long long>(fib(10))); // 55
    std::printf("%lld\n", static_cast<long long>(fib(50))); // 12586269025 % MOD = 586268941
    return 0;
}
```

Uses the [[1,1],[1,0]]^n identity: the top-right entry equals F(n). Products stay under 2^63 since every factor is below 1e9+7, so no overflow before the modulo. Binary exponentiation keeps it O(log n) even for n up to 1e18.

```rust
#[derive(Debug)]
pub struct Node<T> {
    pub value: T,
    pub next: Option<Box<Node<T>>>,
}

/// Iteratively reverses a singly linked list, returning the new head.
pub fn reverse<T>(mut head: Option<Box<Node<T>>>) -> Option<Box<Node<T>>> {
    let mut prev: Option<Box<Node<T>>> = None;

    while let Some(mut node) = head {
        // Take the rest of the list out of this node before re-linking.
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }

    prev
}

