mod tests {
    use super::*;

    fn build(values: &[i32]) -> Option<Box<Node<i32>>> {
        let mut head = None;
        for &v in values.iter().rev() {
            head = Some(Box::new(Node { value: v, next: head }));
        }
        head
    }

    fn collect(mut head: Option<Box<Node<i32>>>) -> Vec<i32> {
        let mut out = Vec::new();
        while let Some(node) = head {
            out.push(node.value);
            head = node.next;
        }
        out
    }

    #[test]
