fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut len = first.len();
    for w in &words[1..] {
        let b = w.as_bytes();
        let mut i = 0;
        while i < len && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    // Safe: prefixes of valid UTF-8 are valid because we compare
    // byte-by-byte over a boundary-aligned prefix from `words[0]`.
    match std::str::from_utf8(&first[..len]) {
        Ok(s) => s.to_owned(),
        Err(_) => {
            // Trim back to a char boundary if a multibyte char was
            // split by a shorter neighbour.
            let s = words[0].as_str();
            let mut end = len;
            while end > 0 && !s.is_char_boundary(end) {
                end -= 1;
            }
            s[..end].to_owned()
        }
    }
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["car".into(), "cart".into()]), "car");
    assert_eq!(longest_common_prefix(&["".into(), "abc".into()]), "");
    assert_eq!(longest_common_prefix(&["dog".into(), "dove".into()]), "do");
    assert_eq!(longest_common_prefix(&["café".into(), "caféine".into()]), "café");
    println!("ok");
}
```

We scan bytes from the first string, shrinking `len` until every word agrees. The fallback trims to a `char` boundary so a multibyte character can't be sliced apart; without it, `from_utf8` would return an error on inputs like `["café", "caf"]`.

