```rust
use std::collections::HashMap;

/// Returns F(n) with F(0)=0, F(1)=1. Fails if the result overflows u128.
pub fn fib(n: u64) -> Result<u128, String> {
    if n > 186 {
        // F(186) is the largest Fibonacci number that fits in u128.
        return Err(format!("F({n}) overflows u128"));
    }
    let mut memo: HashMap<u64, u128> = HashMap::new();
    memo.insert(0, 0);
    memo.insert(1, 1);

    fn go(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
        if let Some(&v) = memo.get(&n) {
            return v;
        }
        let v = go(n - 1, memo).checked_add(go(n - 2, memo)).expect("checked by n <= 186");
        memo.insert(n, v);
        v
    }

    Ok(go(n, &mut memo))
}

fn main() {
    assert_eq!(fib(0).unwrap(), 0);
    assert_eq!(fib(1).unwrap(), 1);
    assert_eq!(fib(10).unwrap(), 55);
    assert_eq!(fib(50).unwrap(), 12586269025);
    assert!(fib(500).is_err());
    println!("F(100) = {}", fib(100).unwrap());
}
```

The recursive helper caches each value the first time it is computed, so the total work is O(n). F(186) is the last Fibonacci value that fits in `u128`, so `n > 186` is rejected up front and the `checked_add` never fires in practice.

