// Returns true on success. Rejects empty, non-digit and overflow input.
bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    bool neg = false;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        s++;
    }
    if (*s == '\0') return false;

    long acc = 0;
    for (; *s != '\0'; s++) {
        if (*s < '0' || *s > '9') return false;
        acc = acc * 10 + (*s - '0');
        if (acc > (long)INT_MAX + 1) return false; // early overflow guard
    }
    if (neg) acc = -acc;
    if (acc < INT_MIN || acc > INT_MAX) return false;
    *out = (int)acc;
    return true;
}

int main(void) {
    int v = 0;
    assert(parse_int("42", &v) && v == 42);
    assert(parse_int("-7", &v) && v == -7);
    assert(parse_int("+15", &v) && v == 15);
    assert(!parse_int("", &v));
    assert(!parse_int("12x", &v));
    assert(!parse_int("-", &v));
    assert(!parse_int("99999999999999999999", &v));
    printf("all tests passed\n");
