import hashlib
import sys
from pathlib import Path


def file_hash(path, chunk_size=65536):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(chunk_size):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root):
    by_hash = {}
    for path in Path(root).rglob("*"):
        if path.is_file():
            try:
                digest = file_hash(path)
            except OSError as exc:
                print(f"skip {path}: {exc}", file=sys.stderr)
                continue
            by_hash.setdefault(digest, []).append(path)
    return {d: files for d, files in by_hash.items() if len(files) > 1}


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    dups = find_duplicates(root)
    if not dups:
        print("no duplicates found")
    for digest, files in dups.items():
        print(f"{digest[:12]}...")
        for f in files:
            print(f"  {f}")
```
Chunked reading keeps memory flat on large files, and grouping by the full digest means only byte-identical files are reported. Pass a directory as the first argument, e.g. `python dups.py ~/Downloads`.

