bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
