pub fn balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' => if stack.pop() != Some('(') { return false; },
            ']' => if stack.pop() != Some('[') { return false; },
            '}' => if stack.pop() != Some('{') { return false; },
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    let cases = [("()[]{}", true), ("([)]", false), ("", true), ("(", false), ("a(b[c])d", true)];
    for (s, want) in cases {
        assert_eq!(balanced(s), want, "input: {:?}", s);
    }
    println!("ok");
}
```

A single stack pass is O(n) time and space. Unmatched closers return early; leftover openers fail the final `is_empty` check. Non-bracket bytes are ignored.

```cpp
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

using namespace std::chrono_literals;

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    // Blocks until there is room. Returns false if the queue is closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return closed_ || q_.size() < capacity_; });
        if (closed_) return false;
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Returns nullopt on timeout or if the queue is closed and drained.
    std::optional<T> pop(std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mu_);
        const auto deadline = std::chrono::steady_clock::now() + timeout;
        while (q_.empty() && !closed_) {
            if (not_empty_.wait_until(lock, deadline) == std::cv_status::timeout) {
                return std::nullopt;
            }
        }
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<T> q_;
    mutable std::mutex mu_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    bool closed_ = false;
};

// Example use:
// BoundedQueue<int> q(2);
// q.push(1); auto v = q.pop(500ms);
