def is_valid_ipv4(address: str) -> bool:
    """Return True only for a canonical dotted-quad IPv4 address.

    Rejects leading zeros ("01"), octets > 255, wrong part count,
    and any non-digit character.
    """
    if not isinstance(address, str):
        return False

    parts = address.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":   # no leading zeros
            return False
        if int(part) > 255:
            return False

    return True


if __name__ == "__main__":
