    invalid = ["256.1.1.1", "01.2.3.4", "1.2.3", "1.2.3.4.5", "a.b.c.d", "", "1..2.3"]
    for ip in valid:
        assert is_valid_ipv4(ip), ip
    for ip in invalid:
        assert not is_valid_ipv4(ip), ip
