fn merge_sorted(a: &[i32], b: &[i32]) -> (Vec<i32>, Vec<i32>) {
    let mut merged = Vec::with_capacity(a.len() + b.len());
    let mut duplicates = Vec::new();
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        let val = if a[i] < b[j] {
            i += 1;
            a[i - 1]
        } else if a[i] > b[j] {
            j += 1;
            b[j - 1]
        } else {
            let v = a[i];
            i += 1;
            j += 1;
            duplicates.push(v);
            v
        };
        merged.push(val);
    }
    merged.extend_from_slice(&a[i..]);
    merged.extend_from_slice(&b[j..]);

    merged.dedup();
    duplicates.dedup();
    (merged, duplicates)
}

fn main() {
    let a = [1, 3, 3, 7];
    let b = [2, 3, 7, 9];
    let (merged, dups) = merge_sorted(&a, &b);
    assert_eq!(merged, vec![1, 2, 3, 7, 9]);
    assert_eq!(dups, vec![3, 7]);
    println!("merged={:?} duplicates={:?}", merged, dups);
}
```

Advancing both indices on equal values records duplicates and avoids emitting the shared value twice. `dedup` cleans up runs created when one input already repeats a value.

