    NonDigit,
    LeadingZero,
    OutOfRange,
}

impl Ipv4 {
    pub fn parse(s: &str) -> Result<Ipv4, ParseError> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 4 {
            return Err(ParseError::WrongPartCount);
        }

        let mut octets = [0u8; 4];
        for (i, part) in parts.iter().enumerate() {
            if part.is_empty() {
                return Err(ParseError::EmptyPart);
            }
            if !part.bytes().all(|b| b.is_ascii_digit()) {
                return Err(ParseError::NonDigit);
            }
            if part.len() > 1 && part.starts_with('0') {
                return Err(ParseError::LeadingZero);
            }
            // part.len() <= 3 here, so parse::<u16> is safe.
            let value: u16 = part.parse().map_err(|_| ParseError::OutOfRange)?;
            if value > 255 {
                return Err(ParseError::OutOfRange);
            }
            octets[i] = value as u8;
        }

        Ok(Ipv4 { octets })
    }
}

fn main() {
    let good = ["0.0.0.0", "127.0.0.1", "255.255.255.255"];
    let bad = ["256.0.0.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.x", "", "1..3.4"];

    for s in good {
        assert!(Ipv4::parse(s).is_ok(), "{s} should parse");
    }
    for s in bad {
        assert!(Ipv4::parse(s).is_err(), "{s} should fail");
    }

    println!("parsed: {:?}", Ipv4::parse("192.168.0.1"));
    println!("rejected: {:?}", Ipv4::parse("192.168.0.256"));
}
```

The parser rejects the subtle cases: leading zeros (`"01"`) which many parsers silently accept, empty parts from `"1..3.4"`, and out-of-range values. Digits are checked before parsing so a huge string can't overflow, and each error variant says exactly what was wrong. `main` finishes with assertions that exercise both the accepted and rejected sets.

```cpp
#include <list>
#include <stdexcept>
#include <unordered_map>
#include <utility>

template <typename K, typename V>
class LRUCache {
    using Entry = std::pair<K, V>;
    using Iter = typename std::list<Entry>::iterator;
    std::size_t capacity_;
    std::list<Entry> order_;                                  // front = MRU
    std::unordered_map<K, Iter> index_;

public:
    explicit LRUCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool get(const K& key, V& out) {
        auto it = index_.find(key);
        if (it == index_.end()) return false;
        order_.splice(order_.begin(), order_, it->second);   // move to front
        out = it->second->second;
        return true;
    }

    void put(const K& key, V value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = std::move(value);
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == capacity_) {
            index_.erase(order_.back().first);
            order_.pop_back();                               // evict LRU
        }
        order_.emplace_front(key, std::move(value));
        index_[key] = order_.begin();
    }
};
```

`std::list::splice` re-links an existing node to the front without copying, so `get` stays O(1). The map stores the list iterator, so lookup and eviction are both O(1). Keys must be hashable and equality-comparable, which `std::unordered_map` already requires.

