```python
from collections.abc import Iterator


class RingBuffer:
    """Fixed-capacity buffer that overwrites the oldest item when full."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data = [None] * capacity
        self._start = 0  # index of oldest item
        self._count = 0

    def push(self, item) -> None:
        if self._count < self._capacity:
            self._data[(self._start + self._count) % self._capacity] = item
            self._count += 1
        else:
            self._data[self._start] = item
            self._start = (self._start + 1) % self._capacity

    def __len__(self) -> int:
        return self._count

    def __iter__(self) -> Iterator:
        for i in range(self._count):
            yield self._data[(self._start + i) % self._capacity]


if __name__ == "__main__":
    rb = RingBuffer(3)
    for x in (1, 2, 3, 4, 5):
        rb.push(x)
    assert list(rb) == [3, 4, 5], list(rb)
    rb.push(6)
    assert list(rb) == [4, 5, 6]
    assert len(rb) == 3
    empty = RingBuffer(2)
    assert list(empty) == []
    print("ring buffer ok")
```
The `_start` index marks the oldest element and wraparound uses modulo, so no shifting or copying happens on overflow. Iteration yields oldest-to-newest in insertion order.

```rust
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn iter(&self) -> impl DoubleEndedIterator<Item = &T> {
        self.items.iter().rev()
    }
}

impl<T> Default for Stack<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut s: Stack<i32> = Stack::new();
    assert!(s.pop().is_none());
    assert!(s.is_empty());

    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.len(), 3);
    assert_eq!(s.peek(), Some(&3));

    let seen: Vec<i32> = s.iter().copied().collect();
    assert_eq!(seen, vec![3, 2, 1]);

    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);

    println!("ok");
}
```
`iter` yields top-to-bottom using `Vec::iter().rev()`, so it composes with `DoubleEndedIterator`. `pop` on empty returns `None`, and `Default` allows `Stack::default()`.

