fn fib(n: u32) -> Option<u64> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(92), Some(7540113804746346429));
    assert_eq!(fib(93), None);
    println!("ok");
}
```

`checked_add` returns `None` the moment `a + b` exceeds `u64::MAX`, so `fib(93)` correctly yields `None` rather than wrapping. The loop is O(n) time, O(1) space, and the asserts cover the base cases and the exact overflow boundary.

