use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

/// Return the field at `idx`, or None if the row is too short.
fn field(fields: &[&str], idx: usize) -> Option<&str> {
    fields.get(idx).copied()
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: {} FILE COLUMN", args[0]);
        std::process::exit(2);
    }
    let path = &args[1];
    let column = &args[2];

    let reader = BufReader::new(File::open(path)?);
    let mut lines = reader.lines();

    let header = match lines.next() {
        Some(Ok(h)) => h,
        _ => {
            eprintln!("input has no header row");
            std::process::exit(1);
        }
    };
    let idx = match header.split(',').position(|c| c.trim() == column) {
        Some(i) => i,
        None => {
            eprintln!("column {:?} not found in header", column);
            std::process::exit(1);
        }
    };

    let (mut sum, mut skipped) = (0.0_f64, 0usize);
    for line in lines {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        match field(&line.split(',').collect::<Vec<_>>(), idx)
            .and_then(|v| v.trim().parse::<f64>().ok())
        {
            Some(v) => sum += v,
            None => skipped += 1,
        }
    }

    println!("sum = {}", sum);
    if skipped > 0 {
        eprintln!("skipped {} malformed row(s)", skipped);
    }
    Ok(())
}
```
Malformed rows (short, empty, non-numeric) are counted and reported on stderr rather than aborting the whole run.

