use std::collections::HashSet;

fn dedup_preserve_order(values: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::with_capacity(values.len());
    let mut result = Vec::with_capacity(values.len());
    for value in values {
        if seen.insert(value) {
            result.push(value);
        }
    }
    result
}

fn main() {
    let input = vec![3, 1, 3, 2, 1, 4];
    let output = dedup_preserve_order(input);
    assert_eq!(output, vec![3, 1, 2, 4]);
    println!("{:?}", output);

    let empty: Vec<i32> = Vec::new();
    assert!(dedup_preserve_order(empty).is_empty());
    println!("empty case ok");
}
```

`HashSet::insert` returns `false` when the value was already present, so each value is pushed exactly once, on first sight. `with_capacity` avoids rehashing for the common case where all values are distinct. The empty input returns an empty vector, and the assert demonstrates the ordering guarantee.

