// Human-readable byte formatting with IEC units.
#include <array>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>

std::string human_bytes(int64_t bytes) {
    constexpr std::array<const char *, 5> units = {"B", "KiB", "MiB", "GiB", "TiB"};

    if (bytes < 0) {
        return "-" + human_bytes(-bytes);
    }
    if (bytes == 0) {
        return "0 B";
    }

    double value = static_cast<double>(bytes);
    size_t unit = 0;
    while (value >= 1024.0 && unit + 1 < units.size()) {
        value /= 1024.0;
        ++unit;
    }

    std::ostringstream out;
    if (unit == 0) {
        out << bytes << " B";  // exact integer bytes
    } else {
        out.setf(std::ios::fixed);
        out.precision(1);
        out << value << ' ' << units[unit];
    }
    return out.str();
}

int main() {
    const int64_t samples[] = {0, -1, 512, 1023, 1024, 1536, 1048576,
                               1073741824LL, 1099511627776LL, 5000000000LL};
    for (int64_t b : samples) {
        std::cout << b << " -> " << human_bytes(b) << '\n';
