template <typename T>
double median(const std::vector<T>& values) {
    if (values.empty()) throw std::invalid_argument("median of empty vector");
    std::vector<T> copy = values;
    std::sort(copy.begin(), copy.end());
    const std::size_t n = copy.size();
    if (n % 2 == 1) return static_cast<double>(copy[n / 2]);
    return (static_cast<double>(copy[n / 2 - 1]) + static_cast<double>(copy[n / 2])) / 2.0;
}

int main() {
