char *reverse_string(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return s;
    }
    size_t left = 0;
    size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
    return s;
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";

    printf("%s\n", reverse_string(a));
    printf("%s\n", reverse_string(b));
    printf("%s\n", reverse_string(c));
    printf("%s\n", reverse_string(NULL) == NULL ? "(null)" : "bad");
    return 0;
}
