#include <vector>

template <typename Container>
auto max_or(const Container& c) -> std::optional<typename Container::value_type> {
    using T = typename Container::value_type;
    std::optional<T> best;
    for (const auto& v : c) {
        if (!best || v > *best) best = v;
    }
    return best;
}

int main() {
    std::vector<int> a{3, 9, 1, 9, 4};
    std::vector<int> empty;
    std::cout << (max_or(a) ? std::to_string(*max_or(a)) : "none") << "\n";
    std::cout << (max_or(empty) ? "some" : "none") << "\n";
    return 0;
}
```
Returning `std::optional<T>` removes the empty-container corner case entirely — no dereferencing an unset iterator. The type is deduced from `Container::value_type`, so it works on `std::vector`, `std::list`, and arrays wrapped in a container.

