```rust
#[derive(Debug)]
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize, // next index to write
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, value: T) {
        self.data[self.head] = Some(value);
        self.head = (self.head + 1) % self.data.len();
        if self.len < self.data.len() {
            self.len += 1;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.data.len();
        let start = (self.head + cap - self.len) % cap;
        (0..self.len).filter_map(move |i| self.data[(start + i) % cap].as_ref())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for v in [1, 2, 3, 4, 5] {
        rb.push(v);
    }
    let out: Vec<&i32> = rb.iter().collect();
    println!("{:?}", out); // [3, 4, 5]
}
```

Pushing past capacity overwrites the oldest entry; `iter` walks from the oldest live slot, deriving the start from `head` and `len` so the order is insertion order.

