class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.buf = [None] * capacity
        self.size = 0
        self.head = 0  # index of next write
        self.tail = 0  # index of oldest element

    def push(self, value):
        self.buf[self.head] = value
        self.head = (self.head + 1) % self.capacity
        if self.size == self.capacity:
            self.tail = (self.tail + 1) % self.capacity
        else:
            self.size += 1

    def pop(self):
        if self.size == 0:
            raise IndexError("buffer is empty")
        value = self.buf[self.tail]
        self.tail = (self.tail + 1) % self.capacity
        self.size -= 1
        return value

    def __len__(self):
        return self.size


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2, 3, 4):
        rb.push(v)
    assert [rb.pop(), rb.pop(), rb.pop()] == [2, 3, 4]
    print("ok")
```

`head` and `tail` both wrap with modulo. When the buffer is full a `push` advances `tail`, so the oldest value is silently dropped — `1` disappears and the pops return `2, 3, 4`.

