fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut n: u64 = 0;
    let mut sum = 0.0f64;
    let mut sum_sq = 0.0f64;

    for line in stdin.lock().lines() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let value: f64 = match trimmed.parse() {
            Ok(v) => v,
            Err(_) => {
                eprintln!("skipping invalid number: {trimmed}");
                continue;
            }
        };

        n += 1;
        sum += value;
        sum_sq += value * value;

        let mean = sum / n as f64;
        let variance = (sum_sq / n as f64) - mean * mean;
        let stddev = variance.max(0.0).sqrt();
        println!("n={n} mean={mean:.4} stddev={stddev:.4}");
    }
    Ok(())
}
```

Welford's identity is avoided here in favour of raw sums, but `variance.max(0.0)` guards against tiny negative values from floating-point cancellation on near-constant input. Invalid lines are reported to stderr and skipped rather than aborting the run, and empty lines are ignored.

```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void destroy(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head = reverse(head);
    for (Node* p = head; p; p = p->next) std::cout << p->value << ' ';
    std::cout << '\n';
    destroy(head);
    return 0;
}
```

`next` is saved before rewriting `head->next`, so no node is lost; `destroy` walks the (now reversed) list and frees each node exactly once.

