```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        fclose(fp);
        return 1;
    }
    long size = ftell(fp);
    if (size < 0) {
        perror("ftell");
        fclose(fp);
        return 1;
    }
    rewind(fp);

    char *buf = malloc((size_t)size + 1);
    if (buf == NULL && size > 0) {
        fprintf(stderr, "out of memory\n");
        fclose(fp);
        return 1;
    }

    size_t got = fread(buf, 1, (size_t)size, fp);
    if (got != (size_t)size && ferror(fp)) {
        perror("fread");
        free(buf);
        fclose(fp);
        return 1;
    }

    buf[got] = '\0';
    printf("read %zu bytes from %s\n", got, argv[1]);

    free(buf);
    fclose(fp);
    return 0;
}
```

Every failure path frees what it allocated and closes the file. Allocating `size + 1` lets us NUL-terminate without a second buffer, and `fread` is compared against the reported size with `ferror` checked, so a short read on a growing file is not treated as success. Empty files allocate one byte and print `read 0 bytes`.

