        int v = (int)value;
        sum += v;
        if (count == 0 || v > max) max = v;
        count++;
    }

    if (count == 0) {
        puts("no integers provided");
        return 0;
    }
    printf("count=%d sum=%lld max=%d\n", count, sum, max);
    return 0;
}
