#include <stdio.h>
#include <stdint.h>

unsigned popcount64(uint64_t x) {
    unsigned count = 0;
    while (x) {
        x &= x - 1;   /* clear the lowest set bit */
        count++;
    }
    return count;
}

int main(void) {
    struct { uint64_t v; unsigned want; } tests[] = {
        {0, 0},
        {1, 1},
        {0xFFFFFFFFFFFFFFFFULL, 64},
        {0x8000000000000001ULL, 2},
        {0x0F0F0F0F0F0F0F0FULL, 32},
    };
    for (size_t i = 0; i < sizeof tests / sizeof tests[0]; i++) {
        unsigned got = popcount64(tests[i].v);
        printf("%016llx -> %u (expected %u)\n",
               (unsigned long long)tests[i].v, got, tests[i].want);
        if (got != tests[i].want) return 1;
    }
    return 0;
}
```
Brian Kernighan's trick iterates once per set bit rather than once per bit position, so it runs faster on sparse values and handles 0 correctly by skipping the loop.

```rust
#[derive(Debug, PartialEq)]
enum ParseError {
    UnexpectedChar(char),
    UnexpectedEnd,
}

struct Parser<'a> {
    chars: std::iter::Peekable<std::str::Chars<'a>>,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { chars: s.chars().peekable() }
    }

    fn parse_expr(&mut self) -> Result<i64, ParseError> {
        let mut value = self.parse_term()?;
        while let Some('+') = self.chars.peek().copied() {
            self.chars.next();
            value += self.parse_term()?;
        }
        Ok(value)
    }

    fn parse_term(&mut self) -> Result<i64, ParseError> {
        let mut value = self.parse_factor()?;
        while let Some('*') = self.chars.peek().copied() {
            self.chars.next();
            value *= self.parse_factor()?;
        }
        Ok(value)
    }

    fn parse_factor(&mut self) -> Result<i64, ParseError> {
        match self.chars.next() {
            Some(c) if c.is_ascii_digit() => {
                let mut n = c.to_digit(10).unwrap() as i64;
                while let Some(d) = self.chars.peek().and_then(|c| c.to_digit(10)) {
                    n = n * 10 + d as i64;
                    self.chars.next();
                }
                Ok(n)
            }
            Some(c) => Err(ParseError::UnexpectedChar(c)),
            None => Err(ParseError::UnexpectedEnd),
        }
    }
}

fn eval(s: &str) -> Result<i64, ParseError> {
    Parser::new(s).parse_expr()
}

fn main() {
    assert_eq!(eval("2+3*4"), Ok(14));
    assert_eq!(eval("10"), Ok(10));
    assert_eq!(eval("2+"), Err(ParseError::UnexpectedEnd));
    assert_eq!(eval("2%3"), Err(ParseError::UnexpectedChar('%')));
    println!("ok");
}
```

The grammar `expr := term ('+' term)*`, `term := factor ('*' factor)*` gives `*` higher precedence than `+` by construction. Multi-digit numbers are read digit by digit, and any non-digit where a factor is expected becomes `UnexpectedChar`.

