```rust
fn running_averages(values: &[f64]) -> Option<Vec<f64>> {
    if values.is_empty() {
        return None;
    }
    let mut means = Vec::with_capacity(values.len());
    let mut sum = 0.0_f64;
    for (i, &v) in values.iter().enumerate() {
        // Compensated (Kahan) addition keeps the mean stable over long inputs.
        let y = v - compensation;
        let t = sum + y;
        compensation = (t - sum) - y;
        sum = t;
        means.push(sum / (i + 1) as f64);
    }
    Some(means)
}

fn main() {
    assert_eq!(running_averages(&[]), None);
    let avgs = running_averages(&[1.0, 2.0, 3.0, 4.0]).unwrap();
    assert_eq!(avgs, vec![1.0, 1.5, 2.0, 2.5]);
    let big = running_averages(&[1e16, 1.0, -1e16]).unwrap();
    assert!((big[2] - 1.0 / 3.0).abs() < 1e-9);
    println!("ok");
}
```

The Kahan compensation term `(t - sum) - y` recovers the low-order bits lost when `sum` is large, so the third mean stays near `1/3` instead of collapsing to `0` from `1e16` swamping `1.0`.

