use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn longest_line(path: &str) -> io::Result<Option<(usize, usize)>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut best: Option<(usize, usize)> = None; // (line_no, byte_len)
    for (idx, line) in reader.lines().enumerate() {
        match line {
            Ok(text) => {
                let n = text.len();
                if best.map_or(true, |(_, b)| n > b) {
                    best = Some((idx + 1, n));
                }
            }
            Err(e) if e.kind() == io::ErrorKind::InvalidData => continue,
            Err(e) => return Err(e),
        }
    }
    Ok(best)
}

fn main() {
    match longest_line("input.txt") {
        Ok(Some((line, len))) => println!("longest: line {} ({} bytes)", line, len),
        Ok(None) => println!("file empty"),
        Err(e) => eprintln!("error: {e}"),
    }
}
