use std::io;

#[derive(Debug)]
pub enum ConfigError {
    Io(io::Error),
    Line { number: usize, reason: String },
}

impl From<io::Error> for ConfigError {
    fn from(e: io::Error) -> Self {
        ConfigError::Io(e)
