pub fn parse_config(text: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();

    for (idx, raw) in text.lines().enumerate() {
        let number = idx + 1;
        let line = raw.trim();

        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let (key, value) = line.split_once('=').ok_or_else(|| ConfigError::Line {
            number,
            reason: format!("missing '=' in {line:?}"),
        })?;

        let key = key.trim();
        let value = value.trim();

        if key.is_empty() {
            return Err(ConfigError::Line {
                number,
                reason: "empty key".to_string(),
            });
        }

        if map.contains_key(key) {
            return Err(ConfigError::Line {
                number,
                reason: format!("duplicate key {key:?}"),
            });
        }

        map.insert(key.to_string(), value.to_string());
    }

    Ok(map)
}

pub fn load(path: &str) -> Result<HashMap<String, String>, ConfigError> {
    parse_config(&fs::read_to_string(path)?)
}

fn main() {
    let text = "# app config\nhost = localhost\nport=8080\n\ndebug = true\n";
    let cfg = parse_config(text).expect("valid config");
    assert_eq!(cfg["host"], "localhost");
    assert_eq!(cfg["port"], "8080");
    assert_eq!(cfg["debug"], "true");

    let bad = "a=1\na=2\n";
    assert!(parse_config(bad).is_err());
    println!("parsed {} keys", cfg.len());
}
