fn parse_pairs(line: &str) -> Option<Vec<(&str, &str)>> {
    let mut out = Vec::new();
    for token in line.split(';') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        let (key, value) = token.split_once('=')?;
        let key = key.trim();
        if key.is_empty() {
            return None;
        }
        out.push((key, value.trim()));
    }
    Some(out)
}

fn main() {
    assert_eq!(parse_pairs("a=1; b=2 ;; c=3").unwrap(),
               vec![("a", "1"), ("b", "2"), ("c", "3")]);
    assert!(parse_pairs("a=1; oops").is_none());
    assert!(parse_pairs("=5").is_none());
    println!("all assertions passed");
}
