def is_valid_ipv4(s):
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


if __name__ == "__main__":
    assert is_valid_ipv4("192.168.0.1") is True
    assert is_valid_ipv4("256.1.1.1") is False
    assert is_valid_ipv4("1.2.3") is False
    assert is_valid_ipv4("01.2.3.4") is False
    assert is_valid_ipv4("1.2.3.4.5") is False
    assert is_valid_ipv4("a.b.c.d") is False
    print("ok")
```

Leading zeros are rejected explicitly, so `01.2.3.4` is invalid even though `int("01")` is 1.

