use std::collections::HashMap;

/// Return the first character that appears exactly once, or None.
/// Operates on Unicode scalar values (chars), not bytes.
fn first_unique_char(s: &str) -> Option<char> {
    let mut counts: HashMap<char, u32> = HashMap::new();
    for ch in s.chars() {
        *counts.entry(ch).or_insert(0) += 1;
    }
    s.chars().find(|ch| counts[ch] == 1)
}

fn main() {
    assert_eq!(first_unique_char("aabbcc"), None);
    assert_eq!(first_unique_char(""), None);
    assert_eq!(first_unique_char("aabbc"), Some('c'));
    assert_eq!(first_unique_char("stress"), Some('t'));
    // Unicode: a combining mark is a distinct scalar value from its base.
    assert_eq!(first_unique_char("éé中"), Some('中'));
    println!("{:?}", first_unique_char("leetcode"));
}
